from pathlib import Path
from lesson_authoring import entry as E
D=[['拉丁 duo“二”相关的 dubius','心在两边摇摆 → 拿不准、怀疑']]
DB=D+[['拉丁 dubitare → 古法语 doter／douter','怀疑、犹豫；也发展出畏惧义'],['中古英语 douten → doubt','怀疑；后来参照拉丁词源补入不发音的 b']]
DU=D+[['晚期拉丁 dubiosus → 英语 dubious','使人怀疑的；自己拿不准的']]
IN=D+[['拉丁 dubitare → dubitabilis → indubitabilis','怀疑 → 可疑的 → 无可怀疑的'],['经拉丁语或法语进入英语 indubitable','无可怀疑的、确定的']]
def A(h,w,m):return h+[[w,m]]
W=[
E('dubious','英 /ˈdjuːbiəs/；美 /ˈduːbiəs/','可疑的；不太可信的；拿不准的','一边想信，一边又觉得哪里不对，心里还没有落定。','拉丁 dubius“摇摆、拿不准”，经相关的晚期拉丁 dubiosus 进入英语；与 doubt 同族，却不是把 doubt 的拼写直接改出来。',DU,'a dubious claim 是让人怀疑的说法；I am dubious about the plan 是我对计划没把握。前一种形容对象可疑，后一种描述人的疑虑。the dubious honour of 常带反讽：这个“荣誉”其实不怎么光彩。','dubious about；of dubious quality；a dubious distinction。','doubtful 更常侧重不确定；dubious 容易带质量、真实性或正当性可疑的意味，但也能单纯说本人拿不准。',('I am dubious about finishing the project by Friday.','我对周五前完成项目没什么把握。'),('The article relies on several dubious claims.','文章依赖了几个不太可信的说法。'),sources=['https://www.etymonline.com/word/dubious']),
E('dubiously','英 /ˈdjuːbiəsli/；美 /ˈduːbiəsli/','怀疑地；以可疑方式；不大可信地','脸上的表情像在说“真是这样吗”，或者事情本身经不起放心相信。','dubious + -ly。',A(DU,'英语 dubiously','以怀疑的态度；在可信性上令人怀疑'),'look dubiously at something 可以是半信半疑地看着它；a dubiously obtained qualification 则说资格的取得方式可疑。副词既能描述人的态度，也能评价做法。','look dubiously；dubiously acquired；dubiously described as。','nervously 是紧张地；dubiously 是带疑虑地，怀疑者不一定紧张。',('She looked dubiously at the handwritten directions.','她半信半疑地看着那份手写路线说明。'),('The object was dubiously described as an ancient treasure.','那件物品被称作古代珍宝，但这一说法很可疑。')),
E('dubiousness','英 /ˈdjuːbiəsnəs/；美 /ˈduːbiəsnəs/','可疑之处；不可信性；疑虑','把“让人没法放心相信”这一性质抽出来说。','dubious + -ness。',A(DU,'英语 dubiousness','可疑、犹疑这一性质'),'the dubiousness of a source 是信息来源的可信程度有问题；the dubiousness of a claim 则关注那句话为什么站不稳。常用在较书面的评价中，日常往往直接说 I have doubts。','the dubiousness of；moral dubiousness。','doubt 是一个疑问或怀疑；dubiousness 常描述对象可疑的性质，也可描述人的犹疑状态。',('The reviewer pointed out the dubiousness of the evidence.','审稿人指出了这些证据的可疑之处。'),('The dubiousness of the offer made her hesitate.','这份邀约不太可信，让她犹豫了。'),sources=['https://en.wiktionary.org/wiki/dubiousness']),
E('dubiety','英 /djuːˈbaɪəti/；美 /duːˈbaɪəti/','疑虑；不确定性〔书面〕','心里还留着一个问号，不能把判断彻底定下来。','借自晚期拉丁 dubietas“怀疑、不确定”，来自 dubius；不是 dubious 在现代英语里直接加 -ty。',D+[['晚期拉丁 dubietas → 英语 dubiety','摇摆、怀疑 → 疑虑、不确定性']],'dubiety 比 doubt 少见，适合阅读较正式或旧式文字。可以说对真实性拿不准，也可以说某个论证让人难以确定。先理解成“仍有疑问”，比死记抽象的“不确定性质”容易。','dubiety about；the dubiety of a claim。','certainty 是确定；dubiety 是疑虑。dubiety 的重音在 /baɪ/，不要照 dubious 的重音位置读。',('There is still some dubiety about the date of the manuscript.','那份手稿的年代仍有一些疑问。'),('The essay explores the dubiety surrounding the witness’s account.','文章讨论了证人叙述周围的疑点。'),sources=['https://www.etymonline.com/word/dubiety']),
E('dubitable','英 /ˈdjuːbɪtəbəl/；美 /ˈduːbɪtəbəl/','可怀疑的；有疑问的〔较少见〕','它还没稳到让人完全放心，有理由继续追问。','拉丁 dubitabilis，来自 dubitare“怀疑”，-bilis 表可……；英语借入这一形容词。',D+[['拉丁 dubitare → dubitabilis','怀疑 → 可以怀疑的'],['英语 dubitable','有疑问的、可质疑的']],'a dubitable conclusion 是仍可质疑的结论。这个词较书面，日常用 doubtful 或 questionable 更常见；认识它也能帮助看懂 indubitable。','a dubitable claim；a dubitable assumption。','debatable 是有讨论或争论余地；dubitable 更直接说真实性、确定性可疑。',('The conclusion rests on a dubitable assumption.','这个结论建立在一个可疑的假设上。'),('The editor removed a sentence containing a dubitable claim.','编辑删掉了一个包含可疑说法的句子。'),sources=['https://www.merriam-webster.com/dictionary/dubitable']),
E('indubitable','英 /ɪnˈdjuːbɪtəbəl/；美 /ɪnˈduːbɪtəbəl/','不容置疑的；确定无疑的〔正式〕','问号已经被可靠依据消掉，几乎没有怀疑空间。','否定 in- + 拉丁 dubitabilis“可疑的”构成 indubitabilis；英语借入后可按 in- + dubitable 理解。',IN,'indubitable evidence 是说证据确凿；an indubitable fact 是强调事实无可置疑。语气很强，使用这个词是在作出明确判断，不是说只要加上它，原本薄弱的证据就会变强。','indubitable evidence；an indubitable fact。','undoubted 常强调公认、无疑；indubitable 更正式、更强调不留下合理怀疑空间。',('The photograph provides indubitable evidence that the bridge existed then.','照片提供了确凿证据，说明那座桥当时已经存在。'),('Her influence on the project is indubitable.','她对项目的影响是毋庸置疑的。'),sources=['https://www.etymonline.com/word/indubitable']),
E('indubitably','英 /ɪnˈdjuːbɪtəbli/；美 /ɪnˈduːbɪtəbli/','无可置疑地；肯定地〔正式〕','用很确定的口气说：这一点没有疑问。','indubitable 的 -le 变为 -ly，得到对应副词形式。',A(IN,'英语 indubitably','无可怀疑地'),'可修饰判断，也可单独回答表示肯定。日常谈话里它容易显得郑重、戏剧化或故意幽默，普通表达往往用 certainly、definitely 或 undoubtedly。','indubitably true；indubitably the best；answer indubitably。','probably 留有不确定；indubitably 表示说话人认为没有疑问，两者语气差得很远。',('The two documents are indubitably connected.','这两份文件之间无疑存在联系。'),('The restoration has indubitably changed the appearance of the building.','修复工作无疑改变了这座建筑的外观。'),sources=['https://www.etymonline.com/word/indubitable']),
E('undoubted','/ʌnˈdaʊtɪd/','无疑的；公认的；确实的','不需要先争一轮，大家就承认这点是真的。','un-“不” + doubted“受到怀疑的”；这一组合在中古英语中已存在。',A(DB,'中古英语 undouted → undoubted','不受怀疑的、明确的'),'her undoubted talent 是她公认的才华；an undoubted success 是确实取得的成功。这个形容词常放在名词前，简洁地肯定某种能力或结果。','undoubted talent；an undoubted success；of undoubted importance。','undoubting 描述人没有怀疑；undoubted 通常描述被认可、未受怀疑的对象或性质。',('Her undoubted talent impressed the whole team.','她无可置疑的才华给整个团队留下了深刻印象。'),('The exhibition was an undoubted success.','这次展览无疑取得了成功。'),sources=['https://en.wiktionary.org/wiki/undoubted']),
E('undoubtedly','/ʌnˈdaʊtɪdli/','无疑；毫无疑问地','先把立场说清楚：我认为这一判断相当确定。','undoubted + -ly；b 不发音，-ed 的 /ɪd/ 保留。',A(DB,'英语 undoubted → undoubtedly','无疑的 → 毫无疑问地'),'常用来加强整句判断：This will undoubtedly help。它表达说话人的确定程度，后面仍需要真实理由支撑；不要把它误读成 /ʌnˈdaʊtbli/。','undoubtedly true；will undoubtedly；undoubtedly one of。','undoubtedly 比 probably 更确定；与 certainly 接近，但通常较适合书面或郑重表达。',('The extra time undoubtedly improved the final design.','多出来的时间无疑改善了最终设计。'),('She is undoubtedly one of the strongest candidates.','她无疑是最有竞争力的候选人之一。'),sources=['https://en.wiktionary.org/wiki/undoubtedly']),
E('doubtfully','/ˈdaʊtfəli/','怀疑地；迟疑地','嘴上可能没说不信，表情和语气已经带着一个问号。','doubtful + -ly；doubt 的 b 不发音。',A(DB,'英语 doubtful → doubtfully','怀疑的、拿不准的 → 带着疑虑地'),'look doubtfully at a plan 是怀疑地看着计划；say doubtfully 是带着不确定的口气说。它通常描述人的表现，不能一律当作“无疑地”，那正好与 doubtless 相反。','look doubtfully；ask doubtfully；shake one’s head doubtfully。','doubtless 常作副词表示无疑或想必；doubtfully 表示带疑虑，字面相像但方向相反。',('He looked doubtfully at the tiny umbrella.','他怀疑地看着那把小小的伞。'),('“Will that really work?” she asked doubtfully.','“那真的能行吗？”她半信半疑地问。'),sources=['https://en.wiktionary.org/wiki/doubtfully']),
E('doubtfulness','/ˈdaʊtfəlnəs/','疑虑；不确定性；可疑性','事情能否成立还悬着，或一个人仍拿不准。','doubtful + -ness。',A(DB,'英语 doubtful → doubtfulness','有疑问的 → 疑虑、不确定这一状态'),'the doubtfulness of an outcome 是结果仍不确定；the doubtfulness in someone’s voice 可以说听出了犹疑。日常可直接用 uncertainty 或 doubt，不必为了显得正式而总选长词。','the doubtfulness of；a tone of doubtfulness。','doubtfulness 可描述人的疑虑或事情的不确定；doubtlessness 则是没有疑问，差一个后缀就转了方向。',('The doubtfulness of the outcome made planning difficult.','结果不确定，使规划变得困难。'),('I could hear doubtfulness in his reply.','我能从他的回答里听出疑虑。'),sources=['https://en.wiktionary.org/wiki/doubtfulness']),
E('doubtlessness','构词参考 /ˈdaʊtləsnəs/','无疑；确定性〔罕见〕','不再左右摇摆，把“没有疑问”这一状态当作名词。','doubt + -less“没有”形成 doubtless，再加 -ness。',A(DB,'英语 doubtless → doubtlessness','没有疑问的 → 无疑这一性质'),'这是少见的抽象名词，阅读时能拆懂即可。普通写作通常用 certainty 或 lack of doubt 更自然；不要把它拆成“较少的疑问”而弱化 -less 的否定作用。','the doubtlessness of；a sense of doubtlessness。','doubtlessness 指没有怀疑；confidence 是信心，两者相关，但自信也可能与证据不足并存。',('The passage contrasts doubtfulness with doubtlessness.','这段文字对比了有疑与无疑两种状态。'),('The narrator describes a brief feeling of doubtlessness.','叙述者描写了一种短暂的毫无疑虑的感觉。'),sources=['https://en.wiktionary.org/wiki/doubtlessness']),
E('dubitation','英 /ˌdjuːbɪˈteɪʃən/；美 /ˌduːbɪˈteɪʃən/','怀疑；犹疑〔古旧〕','判断还在两边晃，暂时没有决定相信哪一边。','经古法语 dubitation 或直接接拉丁 dubitatio，来自 dubitare“怀疑、犹豫”。',D+[['拉丁 dubitare → dubitatio','怀疑 → 怀疑、犹疑这一状态'],['古法语及拉丁语 → 英语 dubitation','怀疑、迟疑的书面名词']],'它与 doubt 大体同义，但带古旧书面感。遇到 without dubitation 可理解成“不加怀疑地”；现代日常表达通常直接说 without doubt。','without dubitation；with some dubitation。','dubitation 并不是“加倍怀疑”；词尾 -ation 把相关动作、状态名词化，不能拿现代 double 硬拆。',('The old letter expresses dubitation about the proposed journey.','那封旧信表达了对拟议旅程的疑虑。'),('He accepted the unusual explanation with some dubitation.','他带着几分疑虑接受了那个不同寻常的解释。'),sources=['https://www.etymonline.com/word/dubitation','https://www.merriam-webster.com/dictionary/dubitation']),
E('redoubtable','/rɪˈdaʊtəbəl/','令人敬畏的；强劲得难以对付的〔书面〕','对方强得让你不敢轻视，既敬佩，也觉得不好招架。','法语 redoutable 接 redouter“畏惧”；re- 在这里加强语气，douter 有怀疑、畏惧的历史意义。',DB[:2]+[['古法语 re- + douter → redouter → redoutable','十分畏惧 → 足以令人敬畏的'],['英语 redoubtable','令人敬畏；强大、难以对付']],'a redoubtable opponent 是实力强劲、让人不敢小看的对手；a redoubtable campaigner 也可赞一个精力旺盛、意志坚定的活动者。它不是“再怀疑一次”，也不只是害怕某个坏人。','a redoubtable opponent；a redoubtable defender。','redoubt 的常见名词“堡垒”来自 reducere“带回”的另一词源；redoubtable 接的是古旧“畏惧”动词支线。',('The young player faced a redoubtable opponent in the final.','那名年轻选手在决赛中面对一位强劲的对手。'),('She became a redoubtable defender of the town’s old library.','她成了镇上老图书馆一位坚定而有力的捍卫者。'),sources=['https://www.etymonline.com/word/redoubtable','https://www.etymonline.com/word/redoubt']),
]
ROOT=dict(id='C0350',meaning='怀疑；两边拿不定主意',core='DUB = DOUBT / TWO MINDS',image='面前分出两条路，心里一会儿偏左、一会儿偏右，还没决定相信哪边。dubius 的“摇摆、不确定”与“二”的词源背景有关；用这个画面理解 doubt，比只背“怀疑”更容易记住。',intro='拉丁 dubius 表示摇摆、拿不准，相关动词 dubitare 表示怀疑、犹豫。经法语走来的一支变成英语 doubt；保留拉丁外形的一支形成 dubious、dubiety 等。历史上的畏惧义又留下 redoubtable。',forms='doubt 的 b 是后来参照拉丁拼写补入的字母，现在不发音；dubious 中的 b 发音。indubitable 的 in- 是否定，undoubted 的 un- 也是否定。现代拆分可以帮助理解，但不表示这些词都由英语 doubt 当场拼出来。',branches=[['心里有疑问','doubt, doubtful, doubter, doubtfully, doubtfulness'],['对象可疑；自己的态度犹疑','dubious, dubiously, dubiousness, dubiety, dubitable, dubitation'],['把疑问排除掉','doubtless, doubtlessness, undoubted, undoubtedly, indubitable, indubitably'],['畏惧的历史支线','redoubtable, redoubt']],contrasts='dubious 可说对象可疑，也可说人拿不准；doubtfully 是怀疑地，doubtless 常表示无疑或想必。redoubt 在本页只联系古旧“畏惧”的动词义；常见“堡垒”名词另有词源，不能凭拼写合并。',practice='I was dubious about the plan, but the demonstration removed my doubts. The improvement was undoubtedly real.\n\n我原本对计划没把握，但演示消除了我的疑虑。改善无疑是真实的。',words=[w['word'] for w in W]+['doubt','doubtful','doubtless','doubter','redoubt'])
if __name__=='__main__':
 for name,v in [('roots_dub',[ROOT]),('words_dub',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(v,ensure_ascii=False,indent=2))
 print(len(W),'individually authored words',sum(len(w['examples']) for w in W),'examples')
